# beverton_holt_recruitment ----
## Setup ----
# Steepness is estimated on the logit scale bounded to (0.2, 1).
logit_steepness <- function(steepness) logit(0.2, 1, steepness)

## IO correctness ----
# The known values are hand calculations of
# R = 0.8 * R0 * h * S / (0.2 * R0 * phi0 * (1 - h) + S * (h - 0.2)).
test_that("`beverton_holt_recruitment()` works with correct inputs", {
  #' @description Test that `beverton_holt_recruitment()` returns 18000 / 21.5 for a spawning biomass of 30, R0 of 1000, steepness of 0.75 and phi0 of 0.1.
  expect_equal(
    object = FIMS:::beverton_holt_recruitment(
      30, log(1000), logit_steepness(0.75), 0.1
    ),
    expected = 18000 / 21.5
  )
  #' @description Test that `beverton_holt_recruitment()` returns R0 at unfished spawning biomass, R0 times phi0.
  expect_equal(
    object = FIMS:::beverton_holt_recruitment(
      1000 * 0.3, log(1000), logit_steepness(0.6), 0.3
    ),
    expected = 1000
  )
})

## Edge handling ----
test_that("`beverton_holt_recruitment()` returns correct outputs for edge cases", {
  # Steepness 0.2 is the lower bound (logit steepness of -Inf). There the
  # curve is the replacement line R = S / phi0, so recruitment does not
  # depend on R0.
  #' @description Test that `beverton_holt_recruitment()` returns S / phi0 = 40 / 0.2 = 200 at steepness 0.2, for a spawning biomass of 40, R0 of 1000 and phi0 of 0.2.
  expect_equal(
    object = FIMS:::beverton_holt_recruitment(
      40, log(1000), logit_steepness(0.2), 0.2
    ),
    expected = 40 / 0.2
  )
  #' @description Test that `beverton_holt_recruitment()` at steepness 0.2 gives S / phi0 for any R0, here 1e6.
  expect_equal(
    object = FIMS:::beverton_holt_recruitment(
      40, log(1e6), logit_steepness(0.2), 0.2
    ),
    expected = 40 / 0.2
  )
})

## Error handling ----
# No built-in errors to test.

# spawning_biomass_per_recruit ----
## Setup ----
# No setup required.

## IO correctness ----
test_that("`spawning_biomass_per_recruit()` works with correct inputs", {
  # With everything mature, weight 1 and all fish female, phi0 is the sum of
  # survival to each age including the plus group, 1 / (1 - exp(-M)).
  #' @description Test that `spawning_biomass_per_recruit()` sums the survival series, including the plus group, when all fish are mature, female and weigh 1.
  expect_equal(
    object = FIMS:::spawning_biomass_per_recruit(
      rep(0.2, 12), 1, rep(1, 12), rep(1, 12)
    ),
    expected = 1 / (1 - exp(-0.2))
  )
})

## Edge handling ----
